function copyToClipboard(text, itemName) {
    var textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.style.position = "fixed";  // per impedire lo scorrimento della pagina
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    try {
 var successful = document.execCommand('copy');
 if (successful) {
 layer.msg(itemName + ' è stato copiato negli appunti', { icon: 1 });
        } else {
 layer.msg('Copia non riuscita, copiare manualmente', { icon: 2 });
 }
    } catch (err) {
 layer.msg('Copia non riuscita, il browser non supporta questa funzione', { icon: 2 });
    }
    document.body.removeChild(textarea);
}

